refentry.refsect1:
&reftitle.description;

 boolheaders_sent
 stringfilename&null;
 intline&null;



 Функция проверяет, инициализировал ли уже скрипт отправку заголовков, и указывает в каком файле и на какой строке начался вывод.



 Нельзя отправить дополнительные строки заголовков функцией header после отправки блока заголовков.
 Функцию headers_sent вызывают, чтобы предупредить ошибки, которые возникают при попытке добавить, изменить или удалить HTTP-заголовки
 после вывода блока заголовков.
 Другой способ избежать ошибок — буферизация вывода.

&reftitle.returnvalues;


 Функция headers_sent вернёт &false;, если HTTP-заголовки
 ещё не отправлялись, иначе вернёт &true;.

  &reftitle.examples;



    Пример проверки факта отправки заголовков функцией headers_sent


<?php

// Отправить заголовок, только если заголовки ещё не отправлялись
if (!headers_sent()) {
    header('Location: http://www.example.com/');
    exit();
}

// Пример заполнения необязательных параметров $filename и $line.
// Переменные $filename и $line не объявляют заранее, а только передают в аргументах,
// значения переменным присвоит функция.
if (!headers_sent($filename, $line)) {
    header('Location: http://www.example.com/');
    exit();

// Модификация заголовков после начала вывода вызовет ошибку
} else {
    echo "Заголовки уже отправлены: вывод начался в файле $filename на строке $line\n" .
          "Невозможно выполнить перенаправление, пожалуйста, перейдите <a " .
          "href=\"http://www.example.com\">по ссылке</a>\n";
    exit();
}

&reftitle.seealso;
ob_start trigger_error headers_list
header — подробное описание работы с заголовками
